"use client";

import { useSearchParams } from "next/navigation";
import { useWorkspaceEntitlements } from "@/components/workspace-quota";
import { Skeleton, WorkspaceSkeleton } from "@/components/workspace-skeleton";

export function TemplatesLoading() {
  const access = useWorkspaceEntitlements();
  const params = useSearchParams();
  if (
    !access.paidGatingEnabled ||
    access.effectivePlan !== "PAID" ||
    params.has("edit") ||
    params.get("new") === "1"
  )
    return <WorkspaceSkeleton page="templates" />;

  return (
    <div role="status" aria-busy="true" aria-label="Loading templates">
      <span className="sr-only">Loading templates…</span>
      <div aria-hidden="true">
        <div className="mb-6 flex flex-wrap items-center justify-between gap-4">
          <div className="space-y-3">
            <Skeleton className="h-4 w-32" />
            <Skeleton className="h-10 w-48" />
            <Skeleton className="h-5 w-80 max-w-full" />
          </div>
          <Skeleton className="h-11 w-36" />
        </div>
        <Skeleton className="mb-2 h-4 w-32" />
        <div className="mb-7 flex gap-2">
          <Skeleton className="h-11 min-w-0 flex-1" />
          <Skeleton className="h-11 w-22" />
        </div>
        <Skeleton className="mb-4 h-6 w-40" />
        <div className="overflow-hidden rounded-2xl border border-border bg-card">
          {Array.from({ length: 6 }, (_, index) => (
            <div
              key={index}
              className="flex items-center justify-between gap-6 border-dotted border-separator p-4 not-first:border-t"
            >
              <div className="min-w-0 flex-1 space-y-2">
                <Skeleton className="h-4 w-1/2" />
                <Skeleton className="h-3 w-3/4" />
              </div>
              <Skeleton className="h-8 w-24" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
